// Read-only access to the full 19–20 May 2024 Curiosity RAD series and the optional-exhibit records.
// Both snapshots are generated by tools/build_science_series.mjs from the read-only research package
// and validated here at load time against the original P2-M02 snapshot (evidence-v1.json).
import rawSeries from './rad-series-v1.json';
import rawExhibits from './exhibits-v1.json';
import {evidence} from './mission';

export type Reading={ts:string;h:number;v:number};
function freezeDeep(value:unknown):void{if(value&&typeof value==='object'){for(const item of Object.values(value))freezeDeep(item);Object.freeze(value)}}
freezeDeep(rawSeries);freezeDeep(rawExhibits);
export const series=rawSeries;
export const exhibitRecords=rawExhibits.records;

const toReadings=(rows:readonly (readonly [string,number])[])=>rows.map(([ts,v])=>({ts,v,h:(Date.parse(ts+'Z')-Date.parse(ts.slice(0,10)+'T00:00:00Z'))/36e5}));
export const MAY19:Reading[]=toReadings(rawSeries.days['2024-05-19'] as unknown as [string,number][]);
export const MAY20:Reading[]=toReadings(rawSeries.days['2024-05-20'] as unknown as [string,number][]);

export const median=(values:number[])=>{const a=[...values].sort((x,y)=>x-y),n=a.length;return n%2?a[(n-1)/2]:(a[n/2-1]+a[n/2])/2};
export const hhmm=(ts:string)=>ts.slice(11,16);

export function validateSeries(s:typeof rawSeries=rawSeries){
  if(s.schemaVersion!==1||s.datasetId!==evidence.datasetId||s.sourceSha256!==evidence.sourceSha256||s.unit!==evidence.derived.unit)throw Error('Series identity mismatch');
  const d20=toReadings(s.days['2024-05-20'] as unknown as [string,number][]),d19=toReadings(s.days['2024-05-19'] as unknown as [string,number][]);
  if(!d20.length||!d19.length)throw Error('Series empty');
  for(const m of evidence.measurements){const r=d20.find(p=>p.ts===m.recordSelector.timestamp);if(!r||r.v!==m.absorbedDoseRate)throw Error('Series row mismatch '+m.recordSelector.timestamp)}
  if(Math.max(...d20.map(r=>r.v))!==evidence.derived.peak)throw Error('Series peak mismatch');
  if(median(d20.map(r=>r.v))!==evidence.derived.eventDayMedian||median(d19.map(r=>r.v))!==evidence.derived.previousDayMedian)throw Error('Series median mismatch');
  if(d20.filter(r=>r.v>evidence.derived.exploratoryCutoff).length!==evidence.derived.readingsAboveExploratoryCutoff)throw Error('Series cutoff count mismatch');
  for(const d of [d19,d20])for(let i=1;i<d.length;i++)if(d[i].h<=d[i-1].h)throw Error('Series not strictly time ordered');
  return true;
}
validateSeries();

export const PEAK=MAY20.reduce((a,b)=>b.v>a.v?b:a);
// Steepest rise between two consecutive real readings (no smoothing).
export const RISE=(()=>{let best=0,i0=1;for(let i=1;i<MAY20.length;i++){const d=MAY20[i].v-MAY20[i-1].v;if(d>best){best=d;i0=i}}return {from:MAY20[i0-1],to:MAY20[i0]}})();
export const WINDOW_HOURS=4;
export type WindowInfo={index:number;start:number;end:number;readings:Reading[];min:number;max:number;kind:'change'|'low'|'falling'};
const baseline=Math.max(...MAY20.filter(r=>r.h<WINDOW_HOURS).map(r=>r.v));
export const WINDOWS:WindowInfo[]=Array.from({length:24/WINDOW_HOURS},(_,i)=>{
  const start=i*WINDOW_HOURS,end=start+WINDOW_HOURS,readings=MAY20.filter(r=>r.h>=start&&r.h<end),vals=readings.map(r=>r.v);
  const kind=RISE.to.h>=start&&RISE.to.h<end?'change':Math.max(...vals)<baseline*3?'low':'falling';
  return {index:i,start,end,readings,min:Math.min(...vals),max:Math.max(...vals),kind};
});
export const CHANGE_WINDOW=WINDOWS.find(w=>w.kind==='change')!;
export const ABOVE_CUTOFF=MAY20.filter(r=>r.v>evidence.derived.exploratoryCutoff);
